import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"51、【震】 震下震上","description":"周易尚氏学 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"周易尚氏学 - 51、【震】 震下震上"},"headers":[],"relativePath":"zh/classics/shangshi/056.md","filePath":"zh/classics/shangshi/056.md"}'),h={name:"zh/classics/shangshi/056.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><p>震振也。动也。一阳伏二阴之下。阳必上升。故振动而为雷。为起。归藏作厘。李过曰厘者理也。黄宗炎曰谓雷厘地而出以作声。愚按震为笑乐。为喜。而厘与僖通。史记以鲁僖公厘公。是其证。说文。傅乐也。与喜同。又震为生为福。而厘亦为福。前汉文帝纪祠官祝厘如淳曰福也。是厘与震义多同。故归藏作厘。周易作震。阳得出故亨。aa？恐惧貌。阳来居初。故日震来。雷之发也。万物震恐。故震来a？a？ 。阳遇阴则通。故笑言哑哑。哑哑笑貌。震为百。艮为里。坎为棘匕。为鬯。鬯柜（左禾）酒也。震为黍。坎为酒。故曰鬯。震惊百里。不丧匕鬯者。言震雷虽威及百里。而不惊惧也。匕所以载牲。曾所以降神。皆祭祀之用。故传曰可以守宗庙为祭主也。</p><p>彖曰。震亨。震来。恐致福也。笑言哑哑。后有则也。震惊百里。惊远而惧迩也。出可以守宗庙社稷。以为祭主也。</p><p>震为福。故曰恐致福。则。法也。互坎为法则。震为后。后有则者。言阳复于下为阴主也。震为出。为祭。为主。艮为守。为社稷。为庙。震为长子。惊远惧迩。能匕鬯不失。故可为祭主。而长守宗庙社稷也。</p><h3 id="洊雷震。君子以恐惧修省。" tabindex="-1">洊雷震。君子以恐惧修省。 <a class="header-anchor" href="#洊雷震。君子以恐惧修省。" aria-label="Permalink to “洊雷震。君子以恐惧修省。”">​</a></h3><p>洊再也。上下震故曰洊雷。 困震而恐，因恐而修省。</p><p>初九。震来虩虩， 后笑言哑哑。吉。</p><p>阳在下。故曰后。言初虽aa？恐惧，后则乐也。阳遇重阴故也。</p><h3 id="象曰。震来虩虩-恐致福也。笑言哑哑。后有则也。" tabindex="-1">象曰。震来虩虩，恐致福也。笑言哑哑。后有则也。 <a class="header-anchor" href="#象曰。震来虩虩-恐致福也。笑言哑哑。后有则也。" aria-label="Permalink to “象曰。震来虩虩，恐致福也。笑言哑哑。后有则也。”">​</a></h3><p>恐则修省。修省则致福。</p><p>震来厉，亿丧贝，跻于九陵。勿逐，七日得。</p><p>来者复也。震来厉。言阳复初。二乘之。故危厉不安也。亿噫通。释文云。本亦作噫。虞翻云。惜辞也。艮为贝。震者艮之覆。故丧贝。古以贝为货币。因厉丧贝。震为言。故曰惜辞。郑作十万解。似不如虞义也。二至四艮。艮为陵。艮阳在上。阳老故曰九陵。震为脐。跃升也。而坎为盗。在艮陵上。言有人持贝。脐九陵以去也。然不必逐也。震为逐。数七。故曰七日。震为复。勿逐七日得者。言所丧之贝。不必追逐。至七日自然来复也。旧解皆以离为贝。易林剥之蒙云。齐贝赎狸。蒙上艮为齐为贝。又谦之蛊。讼之大畜。皆曰丧贝。亦皆以上艮为贝。盖艮坚在外。与离同也。</p><h3 id="象曰。震来厉-乘刚也。" tabindex="-1">象曰。震来厉，乘刚也。 <a class="header-anchor" href="#象曰。震来厉-乘刚也。" aria-label="Permalink to “象曰。震来厉，乘刚也。”">​</a></h3><p>乘刚故危。</p><p>六三。震苏苏。震行无眚。</p><p>苏苏。郑云不安也。坎为疾病。故为眚盖三不当位。故不安。然得阳为承。亦无眚也。</p><h3 id="象曰。震苏苏。位不当也。" tabindex="-1">象曰。震苏苏。位不当也。 <a class="header-anchor" href="#象曰。震苏苏。位不当也。" aria-label="Permalink to “象曰。震苏苏。位不当也。”">​</a></h3><p>虞以苏为死而复生。由象传观之。郑释为当。</p><p>九四。震遂泥。</p><p>遂隧之省文。隧即坠也。论语文武之道。未坠于地。石经作队。又列子。矢隧地而尘不扬。皆以隧为坠。遂古文隧之省。荀子理论篇。人焉而隧。杨惊注云。隧古坠字。故荀爽作隧。四坎为泥。陷四阴中。故隧泥。震为行。隧泥则行难矣。</p><h3 id="象曰。震遂泥。未光也。" tabindex="-1">象曰。震遂泥。未光也。 <a class="header-anchor" href="#象曰。震遂泥。未光也。" aria-label="Permalink to “象曰。震遂泥。未光也。”">​</a></h3><p>坎隐伏。故未光。</p><p>六五。震往来厉，亿无丧，有事。</p><p>往得敌。来乘阳。故往来皆危厉也。自阳遇阳阴遇阴为敌之理失传。于是虞翻不知往厉之故在阴遇阴。只以乘刚为说。乘刚则来厉。于往无涉也。五得中位尊。匕鬯之事。故无丧也。</p><h3 id="象曰。震往来厉。危行也。其事在中。大无丧也。" tabindex="-1">象曰。震往来厉。危行也。其事在中。大无丧也。 <a class="header-anchor" href="#象曰。震往来厉。危行也。其事在中。大无丧也。" aria-label="Permalink to “象曰。震往来厉。危行也。其事在中。大无丧也。”">​</a></h3><p>行。道也。大无丧即亿无丧。</p><p>上六。震索索。视矍矍。征凶。震不于其躬。于其邻。无咎。</p><p>婚媾有言。索索。郑云犹缩缩。足不正也。三在震上。苏苏不安。上亦同也。？？。郑云目不正也。说文。佳欲逸走也。徐曰。左右惊顾也。震。目无上皆。故因恐惧而视矍矍也。易林讼之豫云。眵难无距。与鹊格斗。翅折目盲。为鸠所伤。眵。说文目伤目（上此）也。豫上震。目无上目（上此）。故日眵。曰盲。义即本此也。虞翻不知易用象之妙。以卦无视象。命三变成离取视象。易取象无此迂曲也。三无应。故征凶。震不于其躬于其邻。仍惊远惧迩之意。艮为躬。艮覆为震。故不于其躬于其邻。震为邻。易林蹇之噬嗑云。不利出邻。疾病忧患。噬嗑下震为邻为出。出即与坎险遇。而有疾病忧患之苦。是明以震为邻也。邻仍谓三也。言三苏苏。即知其可惧而戒备也。知惧故无咎。卦二至上正反震。故有言。有言者争讼。与困之三至上正反兑有言不信同也。卦三男俱备。无一女象。故不能婚媾。如婚媾则必争讼也。自覆象失传。此句旧解二千年无一当者。只易林中孚之谦云。伯氏争言。谦亦正覆震。与震二至上同。争言即有言。震为伯也。</p><h3 id="象曰。震索索。中未得也。虽凶无咎。畏邻戒也。" tabindex="-1">象曰。震索索。中未得也。虽凶无咎。畏邻戒也。 <a class="header-anchor" href="#象曰。震索索。中未得也。虽凶无咎。畏邻戒也。" aria-label="Permalink to “象曰。震索索。中未得也。虽凶无咎。畏邻戒也。”">​</a></h3><p>在震上。故曰中未得。因畏而戒。故无咎。</p>',30)])])}const f=e(h,[["render",s]]);export{_ as __pageData,f as default};
